from pathlib import Path
import json
B=Path(__file__).parent
S=[];C={}
def add(k,title,text,forms,notes):
 S.append(dict(id=k,title=title,text=text));C[k]=dict(form=forms,notes=notes)
add('hello','路太多，先算哪条才不白忙？','大家好，我是硅宝，碳硅共鸣的零零一号员工。上集学会先撒点、再排队，老板又问：路这么多，你先查哪一条？我说先查最近的。老板指了指墙：那你先把维修费排进去。',[r'f=g+\hat h'],['第21集 · 第四部分收官','问题：先验证什么？','静态二维规划 · 三维教学展示'])
add('bridge','从排队，走向改进排队的依据','今天认识三个名字：A I T 星、E I T 星，还有较新的 M I T 星。主线只有一句话：一边找路，一边改善指路的信息。前两个方法参考斯特鲁布与加梅尔的论文；第三个是二零二五年提出的多信息树，不是麻省理工学院的简称。这里做自写机制实验，不冒充官方算法性能复现。',[r'\text{estimate}\ \leftrightarrow\ \text{search}'],['AIT* / EIT* / Multi-Informed Trees','教学组件 ≠ 完整论文实现','论文、代码与实验条件见讲义'])
add('heuristic','启发信息：便宜，也要有用','先看熟悉的 A 星。已经走过的代价，加上从当前位置到目标的估计，决定谁先出队。路径长度问题里，直线距离很便宜，也不会高估真实绕行长度。可墙就在面前，直线估计还装作没看见。这里的难题是：估计太粗，队伍排得不聪明；估计太贵，光排队就把下班时间算没了。',[r'f(x)=g(x)+\hat h(x)',r'\hat h_E(x)=\Vert x-x_g\Vert'],['下界：不高估相应最优代价','便宜、准确常有取舍','路径长度与计算时间分开'])
add('reverse','AIT*：从终点反过来估计','A I T 星让两种搜索分工。反向搜索从终点出发，在当前采样图上算到目标的估计；正向搜索利用它，寻找真正可行的路线。原始 A I T 星的反向阶段不做边碰撞检测，所以暂时允许某条边穿墙。注意，那是乐观的计算草稿，不能当成机器人已经能走的路线。',[r'\hat h(v)=\min_u\{\hat c(v,u)+\hat h(u)\}',r'\hat h(x_g)=0'],['反向：计算图上的乐观代价','正向：验证候选边','两棵树职责不同，不能互换'])
add('repair','撞墙的信息，怎样传回去？','正向搜索一旦查出某条边撞墙，就把这个事实反馈给反向搜索，修正受影响的估计，再继续排队。论文用增量修复来节省工作。我们的教学程序为了看清因果，每次直接重算整张反向图，并缓存已验边。因此画面演示的是适应性启发机制，不是完整的 A I T 星实现。',[r'\hat h_{new}\ \leftarrow\ G\setminus E_{invalid}'],['红虚线：已证实无效的边','紫线：反向乐观树，未必可行','教学版全量重算；论文采用增量修复'])
add('aithand','手算：一条坏消息，改变队首','来个独立小账本。两条候选边，甲的已走代价是一，边代价是一，后续估计是一，总共三。乙分别是一、一点五和二，总共四点五，先查甲。查出甲后面那条捷径穿墙，修正后续估计为四，甲就变成六，乙变成队首。启发信息不是预言，是能被证据修正的草稿。',[r'f_A=1+1+1=3',r'f_B=1+1.5+2=4.5',r'f_{A,new}=1+1+4=6'],['独立手算，不是下方点集实测数值','删掉已知无效边，再更新估计','不能随意抬高到超过图上真实最优'])
add('aitrun','真实实验：检查次数与反向工作分开报','再看真实日志。相同地图、相同的二百四十个自由样本、相同一点零五米连边半径。种子一、七、十七，固定直线启发分别验了二百五十六、二百六十四、二百三十六条边；适应性版本是九十六、一百一十五、一百一十二条。两者在每个种子上得到相同的图上最短长度，独立全验图也核对通过。',[r'N=240,\quad r=1.05\,m'],['三种子：1 / 7 / 17','固定 / 适应：256/96，264/115，236/112','仅本场景、冻结采样图，不作算法排名'])
add('account','少验边，不自动等于更快','好消息是本例少验了一些边。坏消息是，反向重算也要干活。三组适应性实验额外访问了上万条反向邻接边，还要维护缓存和队列。这些工作没有藏起来。边检碰次数、反向图工作、实际运行时间，应分别记录。电脑少敲了几下门，不代表它没绕着小区跑三圈。',[r'T=T_{sample}+T_{reverse}+T_{forward}+T_{check}'],['边检碰：每条新边一次解析检查','反向邻接访问另记，不计为检碰','低维轻量检查不能代表机械臂耗时'])
add('effort','EIT*：还要估计验证的工作量','如果优化的是复杂代价，便宜又有用的代价下界可能很难找。E I T 星还引入剩余计算工作的估计，例如验证候选路径大概需要多少次状态检查。它同时利用代价下界、代价估计和工作量估计；反向阶段也会做自适应的稀疏检查。路短不短，与验证费不费劲，是两本账。',[r'\hat h:\ \text{lower bound}',r'\bar h:\ \text{cost estimate}',r'\bar e:\ \text{effort estimate}'],['工作量估计不要求是下界','原方法：AEES式正向边队列','稀疏检查提供信息，不能替代最终验证'])
add('bounded','小账本：先找可用，再收紧要求','用一个独立候选路线账本说明取舍。甲的目标代价六，预计六十次状态检查；乙的目标代价七，预计十二次。当前代价下界六，暂时允许一点二倍，也就是七点二以内。两条都合格，就可以先验证预计省事的乙。要求收紧到一倍以后，乙不再合格，必须继续检查甲。',[r'L=6,\quad w=1.2',r'c\leq wL=7.2',r'w\downarrow 1'],['合成目标代价6/7，不是图中几何长度','教学候选筛选，不是EIT*完整伪代码','初解速度与最终路径质量分别衡量'])
add('effortrun','真实执行账本：十二次之后还没结束','程序实际执行了这份状态检查账本。宽松阶段，十二次检查拿到乙；收紧后再做六十次，得到代价六的甲，累计七十二次。先拿可用路线，并不等于总工作一定更少。这个例子只解释计算分配，没有证明 E I T 星比别的方法快；真实论文的队列规则和界限维护，比这张账本完整得多。',[r'12\ \to\ 12+60=72',r'7\ \to\ 6'],['状态检查计数 ≠ 边检查计数','未模拟每次检查的真实耗时','图上代价单位与几何长度明确分开'])
add('mit','MIT*：还没有可行路，采样往哪儿放？','最后介绍 M I T 星，英文是多信息树。它在首条可行路线出现前，也利用懒搜索得到的信息构造估计采样区域，并结合障碍附近的自适应采样，以及与边长相关的稀疏检查。已经找到真实路线时，可以用真实代价定义改进域；还没找到时，估计域只是引导，不能冒充已知可行解的上界。',[r'c_{best}\neq \tilde s_{est}'],['2025年研究介绍 · 非官方复现','估计域、自适应采样、稀疏检查','未验证的懒路径不能当成可行解'])
add('mithand','论文公式与独立手算','论文把已验证前缀代价、待验边下界、后续下界相加，形成一个初步估计，再用扩张因子放大。独立手算里，三个数是二、一、二，相加五；前缀占比是零点四，扩张因子约一点一六六，估计阈值约五点八三一。这个占比是算法构造量，不是成功概率，也不是说百分之四十不会撞墙。',[r'\hat s=g_F+\hat c+\hat h',r'\gamma=g_F/\hat s',r'e_\gamma=\sqrt{1+(1-\gamma)^2}',r'\tilde s=\hat s e_\gamma'],['2+1+2=5；γ=0.4','e≈1.166；估计阈值≈5.831','独立手算；不把γ解释为成功率'])
add('ellipse','把估计阈值变成一个区域','在二维路径长度问题里，把到起点和终点的直线距离相加，小于阈值的点画出来，就是一个椭圆区域。两端相距五米时，长半轴是阈值的一半，短半轴由平方差开方再除二。我们的程序真正在域内采样并检查障碍，还保留遇到障碍后向附近寻找自由点的组件实验。',[r'\Vert x-x_s\Vert+\Vert x-x_g\Vert<\tilde s',r'a=\tilde s/2',r'b=\sqrt{\tilde s^2-25}/2'],['这里只演示采样组件，非完整MIT*','障碍附近偏置不保证命中窄通道','采样仍要检查域边界与碰撞'])
add('failure','故意失败：把真正的绕行空间剪掉了','现在故意把阈值压到五点零五米。中间有半径一米的圆障碍，可椭圆在中线处只允许上下约零点三五四米。任何连续路线都得经过中线，那里整个都被障碍封住，样本再多也没用。这不是地图没有路，是我把门锁在采样域外了。老板说，这叫优化。我说，这叫优化掉了下班的可能。',[r'\tilde s=5.05\,m',r'b\approx0.354\,m<1\,m'],['真实失败：320样本，未找到路','中线截面给出几何阻断证据','局部估计域无解 ≠ 整个环境无解'])
add('recovery','恢复：扩大域，再验证整段','把阈值放宽到六点二米，保持三百二十个自由样本与原连边半径，种子一得到约五点四五六米的可行折线，并通过解析整段检碰。这里直接设置两个阈值，是边界教学实验，不是完整实现论文的自动扩域策略。真正的规划器要根据失败继续扩大覆盖、补采样和重搜，不能守着一个过窄区域宣布无路。',[r'\tilde s:5.05\to6.2',r'c_{graph}\approx5.4564\,m'],['阈值对照是教学控制变量','两域采样位置不同；不比较速度','所有返回线段均做解析检碰'])
add('sparse','稀疏检查：没查出，不等于没有','还有个容易踩的坑。零到五米的一条线，障碍藏在一点二五米处，半径零点一二米。只查两端和中点，三个点都安全，整条线却穿过障碍。程序把这个漏检保留下来，增加到一百零一个等距点就发现了；但离散加密对任意更小障碍也不万能。本集圆障碍最终用解析线段检查作裁判。',[r'\{0,0.5,1\}:\ \text{pass}',r'\text{segment}:\ \text{collision}'],['三点通过，101点发现本例障碍','离散检查依赖分辨率','反向草稿与最终验证严格分开'])
add('limits','星号的边界：渐近，不是这次保证','几个名字都带星，也别把星号读成包过。论文性质有采样、连接、验证和持续计算等前提。有限样本上的最短路线，只是当前图上的最短，不等于连续空间全局最短。我们的二维点机器人、解析圆障碍与教学组件，也没有复现高维机械臂、真机执行或者官方论文的完整渐近性质。',[r'c_G^*\neq c_{continuous}^*'],['有限预算：允许无解，允许次优','不从教学组件推导论文性能结论','静态场景；非真机、非动态重规划'])
add('map','第四部分收官：按问题找工具','第四部分到这里收官。局部下坡容易卡，想起人工势场；多次查询想复用路网，想起 P R M；整条轨迹要一起改，想起前面两集的轨迹优化；批量采样结合搜索，想起 F M T 和 B I T；排队依据与计算分配不够聪明，再研究今天这组方法。它们回答的需求不同，没有一个名字能替所有场景签收。',[r'\text{problem}\ \to\ \text{mechanism}\ \to\ \text{validation}'],['16 势场；17 PRM/Lazy PRM','18 CHOMP/STOMP；19 TrajOpt/GPMP2','20 FMT*/BIT*；21 AIT*/EIT*/MIT*'])
add('close','不是多算一点，而是知道为什么算','今天记住三句话：估计可以更新，工作量要单独算，没验过的路线不能交付。算法名字越学越多，验收标准不能越学越少。我是硅宝，代码、讲义和真实日志会一起留好。下次继续练级，这次先把老板的维修账单关掉。',[r'\text{estimate}\to\text{check}\to\text{repair}'],['第四部分15—21集收官','代码、公式、日志与适用条件公开','画面与配音含AI辅助制作'])
(B/'lesson.json').write_text(json.dumps(S,ensure_ascii=False,indent=2));(B/'cards.json').write_text(json.dumps(C,ensure_ascii=False,indent=2))
print('chapters',len(S),'chars',sum(len(s['text'])for s in S))
